#!/usr/bin/env python3
"""
Generate the final HTML report for Global Intentional Homicide Trends (1990–2023)
"""
import pandas as pd
import numpy as np
import json
import os

# ============================================================
# LOAD & PREPARE DATA
# ============================================================
df = pd.read_csv('/app/benchmark/data.csv')
df_both_all = df[(df['sex'] == 'both') & (df['age_group'] == 'ALL')].copy()
df_male_all = df[(df['sex'] == 'male') & (df['age_group'] == 'ALL')].copy()
df_female_all = df[(df['sex'] == 'female') & (df['age_group'] == 'ALL')].copy()
df_age_m = df[(df['sex'] == 'male') & (df['age_group'] != 'ALL')].copy()
df_age_f = df[(df['sex'] == 'female') & (df['age_group'] != 'ALL')].copy()

REGION_MAP = {
    'ATG':'Americas','ARG':'Americas','BHS':'Americas','BRB':'Americas','BLZ':'Americas',
    'BOL':'Americas','BRA':'Americas','CAN':'Americas','CHL':'Americas','COL':'Americas',
    'CRI':'Americas','CUB':'Americas','DMA':'Americas','DOM':'Americas','ECU':'Americas',
    'SLV':'Americas','GRD':'Americas','GTM':'Americas','GUY':'Americas','HTI':'Americas',
    'HND':'Americas','JAM':'Americas','MEX':'Americas','NIC':'Americas','PAN':'Americas',
    'PRY':'Americas','PER':'Americas','PRI':'Americas','KNA':'Americas','LCA':'Americas',
    'VCT':'Americas','SUR':'Americas','TTO':'Americas','USA':'Americas','URY':'Americas',
    'VEN':'Americas',
    'ALB':'Europe','AUT':'Europe','BLR':'Europe','BEL':'Europe','BIH':'Europe',
    'BGR':'Europe','HRV':'Europe','CZE':'Europe','DNK':'Europe','EST':'Europe',
    'FIN':'Europe','FRA':'Europe','DEU':'Europe','GRC':'Europe','HUN':'Europe',
    'ISL':'Europe','IRL':'Europe','ITA':'Europe','LVA':'Europe','LTU':'Europe',
    'LUX':'Europe','MLT':'Europe','MDA':'Europe','MNE':'Europe','NLD':'Europe',
    'MKD':'Europe','NOR':'Europe','POL':'Europe','PRT':'Europe','ROU':'Europe',
    'RUS':'Europe','SRB':'Europe','SVK':'Europe','SVN':'Europe','ESP':'Europe',
    'SWE':'Europe','CHE':'Europe','UKR':'Europe','GBR':'Europe','AND':'Europe',
    'LIE':'Europe','MCO':'Europe','SMR':'Europe','XKX':'Europe',
    'AFG':'Asia','BGD':'Asia','BTN':'Asia','IND':'Asia','IRN':'Asia',
    'KAZ':'Asia','KGZ':'Asia','LKA':'Asia','MDV':'Asia','MMR':'Asia',
    'MNG':'Asia','NPL':'Asia','PAK':'Asia','TJK':'Asia','TKM':'Asia',
    'UZB':'Asia','CHN':'Asia','JPN':'Asia','KOR':'Asia','PRK':'Asia',
    'HKG':'Asia','MAC':'Asia','TWN':'Asia','BRN':'Asia','IDN':'Asia',
    'KHM':'Asia','LAO':'Asia','MYS':'Asia','PHL':'Asia','SGP':'Asia',
    'THA':'Asia','TLS':'Asia','VNM':'Asia','ARM':'Asia','AZE':'Asia',
    'BHR':'Asia','CYP':'Asia','GEO':'Asia','IRQ':'Asia','ISR':'Asia',
    'JOR':'Asia','KWT':'Asia','LBN':'Asia','OMN':'Asia','PSE':'Asia',
    'QAT':'Asia','SAU':'Asia','SYR':'Asia','TUR':'Asia','ARE':'Asia','YEM':'Asia',
    'DZA':'Africa','AGO':'Africa','BEN':'Africa','BWA':'Africa','BFA':'Africa',
    'BDI':'Africa','CMR':'Africa','CPV':'Africa','CAF':'Africa','TCD':'Africa',
    'COM':'Africa','COG':'Africa','COD':'Africa','DJI':'Africa','EGY':'Africa',
    'GNQ':'Africa','ERI':'Africa','ETH':'Africa','GAB':'Africa','GMB':'Africa',
    'GHA':'Africa','GIN':'Africa','GNB':'Africa','CIV':'Africa','KEN':'Africa',
    'LSO':'Africa','LBR':'Africa','LBY':'Africa','MDG':'Africa','MWI':'Africa',
    'MLI':'Africa','MRT':'Africa','MUS':'Africa','MAR':'Africa','MOZ':'Africa',
    'NAM':'Africa','NER':'Africa','NGA':'Africa','RWA':'Africa','STP':'Africa',
    'SEN':'Africa','SLE':'Africa','SOM':'Africa','ZAF':'Africa','SSD':'Africa',
    'SDN':'Africa','SWZ':'Africa','TZA':'Africa','TGO':'Africa','TUN':'Africa',
    'UGA':'Africa','ZMB':'Africa','ZWE':'Africa',
    'AUS':'Oceania','FJI':'Oceania','NZL':'Oceania','PNG':'Oceania','WSM':'Oceania',
    'KIR':'Oceania','MHL':'Oceania','FSM':'Oceania','NRU':'Oceania','PLW':'Oceania',
    'SLB':'Oceania','TON':'Oceania','TUV':'Oceania','VUT':'Oceania',
}

df_both_all['region'] = df_both_all['iso_code'].map(REGION_MAP).fillna('Other')

# ============================================================
# COMPUTE ALL METRICS
# ============================================================

# Global trend by year
global_trend = df_both_all.groupby('year')['homicide_rate'].agg(
    median='median', mean='mean',
    q25=lambda x: x.quantile(0.25),
    q75=lambda x: x.quantile(0.75)
).reset_index()

# Countries per year
countries_per_year = df_both_all.groupby('year')['country'].nunique().reset_index()
countries_per_year.columns = ['year', 'count']
max_countries = df_both_all['country'].nunique()
countries_per_year['coverage'] = (countries_per_year['count'] / max_countries * 100).round(1)

# Gender trend
male_by_year = df_male_all.groupby('year')['homicide_rate'].median().reset_index()
male_by_year.columns = ['year', 'male']
female_by_year = df_female_all.groupby('year')['homicide_rate'].median().reset_index()
female_by_year.columns = ['year', 'female']
gender_trend = pd.merge(male_by_year, female_by_year, on='year', how='inner')
gender_trend['ratio'] = (gender_trend['male'] / gender_trend['female']).round(3)

# KPIs
most_recent_year = int(df_both_all['year'].max())
df_recent = df_both_all[df_both_all['year'] == most_recent_year]
global_median = float(df_recent['homicide_rate'].median())
global_mean = float(df_recent['homicide_rate'].mean())

# MF ratio at most recent year with both
merged_mf_recent = pd.merge(
    df_male_all[['country','year','homicide_rate']].rename(columns={'homicide_rate':'m'}),
    df_female_all[['country','year','homicide_rate']].rename(columns={'homicide_rate':'f'}),
    on=['country','year']
)
merged_mf_recent['ratio'] = merged_mf_recent['m'] / merged_mf_recent['f'].replace(0, np.nan)
mf_recent_year = int(merged_mf_recent['year'].max())
global_mf_ratio = float(merged_mf_recent[merged_mf_recent['year']==mf_recent_year]['ratio'].median())

# Highest country
most_recent_per_country = df_both_all.loc[df_both_all.groupby('country')['year'].idxmax()].copy()
highest = most_recent_per_country.loc[most_recent_per_country['homicide_rate'].idxmax()]
top10 = most_recent_per_country.nlargest(10, 'homicide_rate')
bottom10 = most_recent_per_country.nsmallest(10, 'homicide_rate')

# Decade averages
def decade_avg(start, end):
    return float(df_both_all[(df_both_all['year']>=start)&(df_both_all['year']<=end)]['homicide_rate'].mean())

d90 = decade_avg(1990, 1999)
d00 = decade_avg(2000, 2009)
d10 = decade_avg(2010, 2019)
d20 = decade_avg(2020, 2023)
pct_00 = (d00-d90)/d90*100
pct_10 = (d10-d00)/d00*100
pct_20 = (d20-d10)/d10*100

# Coverage
countries_2023 = len(df_both_all[df_both_all['year']==2023])
coverage_pct = float(countries_2023 / max_countries * 100)

# Regional by year
region_by_year = df_both_all.groupby(['year','region'])['homicide_rate'].median().reset_index()

# Top declines / increases
country_fl = []
for country, grp in df_both_all.groupby('country'):
    grp_s = grp.sort_values('year')
    if len(grp_s) >= 5:
        first, last = grp_s.iloc[0], grp_s.iloc[-1]
        if first['homicide_rate'] > 0:
            pct = (last['homicide_rate'] - first['homicide_rate']) / first['homicide_rate'] * 100
            country_fl.append({
                'country': country,
                'first_year': int(first['year']),
                'last_year': int(last['year']),
                'first_rate': round(float(first['homicide_rate']), 2),
                'last_rate': round(float(last['homicide_rate']), 2),
                'pct_change': round(float(pct), 1),
            })
df_fl = pd.DataFrame(country_fl)
top_declines = df_fl.nsmallest(8, 'pct_change').to_dict('records')
top_increases = df_fl.nlargest(8, 'pct_change').to_dict('records')

# Age group data (male, averaged globally)
age_trend = df_age_m.groupby(['year','age_group'])['homicide_rate'].median().reset_index()
age_groups_ordered = ['0_9','10_14','15_17','18_19','20_24','25_29','30_44','45_59','60_PLUS']
age_labels = {'0_9':'0–9','10_14':'10–14','15_17':'15–17','18_19':'18–19',
              '20_24':'20–24','25_29':'25–29','30_44':'30–44','45_59':'45–59','60_PLUS':'60+'}

# Age group overall median (male)
age_overall = df_age_m.groupby('age_group')['homicide_rate'].median().reset_index()
age_overall = age_overall[age_overall['age_group'].isin(age_groups_ordered)]
age_overall['age_group'] = pd.Categorical(age_overall['age_group'], categories=age_groups_ordered, ordered=True)
age_overall = age_overall.sort_values('age_group')

# ============================================================
# PREPARE JSON DATA FOR CHARTS
# ============================================================
def to_js(v):
    if isinstance(v, float) and np.isnan(v):
        return 'null'
    return v

# Global trend data
gt_years = global_trend['year'].tolist()
gt_median = [round(float(v),3) for v in global_trend['median'].tolist()]
gt_mean = [round(float(v),3) for v in global_trend['mean'].tolist()]
gt_q25 = [round(float(v),3) for v in global_trend['q25'].tolist()]
gt_q75 = [round(float(v),3) for v in global_trend['q75'].tolist()]

# Gender trend data
ge_years = gender_trend['year'].tolist()
ge_male = [round(float(v),3) for v in gender_trend['male'].tolist()]
ge_female = [round(float(v),3) for v in gender_trend['female'].tolist()]
ge_ratio = [round(float(v),3) for v in gender_trend['ratio'].tolist()]

# Regional data
regions = ['Americas','Europe','Asia','Africa','Oceania']
region_colors = {
    'Americas': '#e74c3c',
    'Europe': '#3498db',
    'Asia': '#2ecc71',
    'Africa': '#f39c12',
    'Oceania': '#9b59b6',
}
all_years = sorted(df_both_all['year'].unique())
regional_datasets = {}
for reg in regions:
    rdata = region_by_year[region_by_year['region']==reg].set_index('year')['homicide_rate']
    regional_datasets[reg] = [round(float(rdata.get(y, float('nan'))), 3) if y in rdata.index else None for y in all_years]

# Age chart
age_vals = [round(float(v),3) for v in age_overall['homicide_rate'].tolist()]
age_labs = [age_labels[a] for a in age_overall['age_group'].tolist()]

# Top 10 / Bottom 10
top10_names = top10['country'].tolist()
top10_rates = [round(float(v),2) for v in top10['homicide_rate'].tolist()]
top10_years = top10['year'].tolist()

bottom10_names = bottom10['country'].tolist()
bottom10_rates = [round(float(v),3) for v in bottom10['homicide_rate'].tolist()]
bottom10_years = bottom10['year'].tolist()

# Coverage
cov_years = countries_per_year['year'].tolist()
cov_counts = countries_per_year['count'].tolist()

# ============================================================
# BUILD HTML
# ============================================================
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #1a2744;
    --accent: #c0392b;
    --accent2: #2980b9;
    --light: #f4f6fa;
    --border: #dde3ef;
    --text: #1c2b3a;
    --muted: #6c7a8d;
    --green: #27ae60;
    --orange: #e67e22;
    --card-bg: #ffffff;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Segoe UI', system-ui, sans-serif;
    background: var(--light);
    color: var(--text);
    font-size: 14.5px;
    line-height: 1.65;
  }}
  /* HEADER */
  .report-header {{
    background: linear-gradient(135deg, #1a2744 0%, #243b6e 60%, #1a5276 100%);
    color: white;
    padding: 48px 60px 40px;
  }}
  .report-header .label {{
    font-size: 11px;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.6);
    margin-bottom: 12px;
  }}
  .report-header h1 {{
    font-size: 28px;
    font-weight: 700;
    line-height: 1.3;
    margin-bottom: 10px;
    max-width: 750px;
  }}
  .report-header .subtitle {{
    font-size: 14px;
    color: rgba(255,255,255,0.72);
    max-width: 680px;
  }}
  .report-header .meta {{
    margin-top: 20px;
    display: flex;
    gap: 28px;
    font-size: 12px;
    color: rgba(255,255,255,0.55);
  }}
  /* MAIN */
  .report-body {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 36px 28px 60px;
  }}
  /* KPI DASHBOARD */
  .kpi-strip {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 36px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 16px 18px;
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--accent);
  }}
  .kpi-card.blue::before {{ background: var(--accent2); }}
  .kpi-card.green::before {{ background: var(--green); }}
  .kpi-card.orange::before {{ background: var(--orange); }}
  .kpi-card.purple::before {{ background: #8e44ad; }}
  .kpi-value {{
    font-size: 26px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 4px;
    line-height: 1;
  }}
  .kpi-label {{
    font-size: 11.5px;
    color: var(--muted);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }}
  .kpi-sub {{
    font-size: 11px;
    color: var(--muted);
    margin-top: 6px;
  }}
  /* SECTIONS */
  .section {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 30px;
    margin-bottom: 28px;
  }}
  .section-header {{
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 20px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--border);
  }}
  .section-num {{
    background: var(--primary);
    color: white;
    font-size: 11px;
    font-weight: 700;
    width: 26px; height: 26px;
    border-radius: 6px;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    margin-top: 1px;
  }}
  .section-title {{
    font-size: 18px;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.2;
  }}
  .section-objective {{
    font-size: 12.5px;
    color: var(--muted);
    margin-top: 3px;
  }}
  /* CHART CONTAINERS */
  .chart-container {{
    position: relative;
    height: 320px;
    margin: 16px 0;
  }}
  .chart-container.tall {{
    height: 380px;
  }}
  .chart-container.short {{
    height: 240px;
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 16px 0;
  }}
  /* ANALYSIS TEXT */
  .insight-box {{
    background: #f0f4fa;
    border-left: 4px solid var(--accent2);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    margin: 16px 0;
    font-size: 13.5px;
  }}
  .insight-box.warn {{
    background: #fef9f0;
    border-left-color: var(--orange);
  }}
  .insight-box.success {{
    background: #edfaf4;
    border-left-color: var(--green);
  }}
  p.body-text {{
    font-size: 13.5px;
    color: #2c3e50;
    margin-bottom: 12px;
    line-height: 1.7;
  }}
  /* TABLES */
  .table-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-top: 18px;
  }}
